//! Move plan for reordering an [`IndexMap`] to a target key order.
//!
//! This module provides [`MovePlan`], a read-only plan generated by
//! [`IndexMap::plan_move_to`] that describes how to reorder a map to a
//! target key order using a minimum number of [`move_index`][IndexMap::move_index]
//! operations. The plan is executed by [`IndexMap::apply_move_plan`], which
//! first verifies that the map's original order hasn't been rearranged.
//!
//! # Algorithm
//!
//! The plan keeps a [longest common subsequence] (LCS) of the current and
//! target key orders fixed, and moves each remaining key exactly once to its
//! target position. This minimizes the number of move operations. When multiple
//! LCS exist, the one whose original positions are lexicographically smallest is
//! chosen (preferring to keep keys that appear earlier in the original order).
//!
//! Each move's indices are computed by simulating the map state after the
//! previous moves, so they are valid at execution time.
//!
//! [longest common subsequence]: https://en.wikipedia.org/wiki/Longest_common_subsequence
//!
//! # Examples
//!
//! ```
//! use indexmap::IndexMap;
//!
//! let mut map: IndexMap<&str, i32> = IndexMap::new();
//! map.insert("a", 1);
//! map.insert("b", 2);
//! map.insert("c", 3);
//! map.insert("d", 4);
//!
//! // Generate a plan to reorder to b, c, a, d.
//! let target = ["b", "c", "a", "d"];
//! let plan = map.plan_move_to(&target).unwrap();
//!
//! // Only one move is needed: move "a" to its target position.
//! assert_eq!(plan.len(), 1);
//!
//! // Apply the plan.
//! map.apply_move_plan(&plan).unwrap();
//! assert_eq!(map.keys().copied().collect::<Vec<_>>(), vec!["b", "c", "a", "d"]);
//! assert_eq!(map[&"a"], 1); // values are unchanged
//! assert_eq!(map[&"b"], 2);
//! ```

use alloc::vec::Vec;
use core::hash::{BuildHasher, Hash};

use crate::map::IndexMap;

/// A single move operation in a [`MovePlan`].
///
/// The move moves the key-value pair at index `from` to index `to`,
/// shifting other pairs as needed (like [`IndexMap::move_index`]).
///
/// Indices are valid at the step the move is executed, assuming the map
/// starts in the fingerprinted state (see [`MovePlan::fingerprint`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Move {
    /// The index of the key-value pair to move.
    pub from: usize,
    /// The index to move the pair to.
    pub to: usize,
}

/// A plan for reordering an [`IndexMap`] to a target key order.
///
/// The plan is generated by [`IndexMap::plan_move_to`] and executed by
/// [`IndexMap::apply_move_plan`]. It contains:
///
/// - A sequence of [`Move`] operations, in execution order. Each move's
///   indices are computed based on the map state after the previous moves.
/// - A fingerprint of the original key order, used to verify the map
///   hasn't been rearranged before execution.
///
/// The plan is read-only once generated; applying it does not modify the
/// plan.
///
/// # Plan format
///
/// The plan is a sequence of `(from, to)` pairs followed by the original
/// key-order fingerprint. For example, reordering `[a, b, c, d]` to
/// `[b, c, a, d]` produces a single move `(0, 2)` (move `a` from index 0
/// to index 2), with fingerprint `[a, b, c, d]`.
#[derive(Clone, Debug)]
pub struct MovePlan<K> {
    moves: Vec<Move>,
    fingerprint: Vec<K>,
}

impl<K> MovePlan<K> {
    /// Returns the move operations in execution order.
    pub fn moves(&self) -> &[Move] {
        &self.moves
    }

    /// Returns the number of move operations.
    pub fn len(&self) -> usize {
        self.moves.len()
    }

    /// Returns `true` if the plan has no move operations.
    pub fn is_empty(&self) -> bool {
        self.moves.is_empty()
    }

    /// Returns the original key-order fingerprint.
    ///
    /// This is the key order at the time the plan was generated.
    /// [`IndexMap::apply_move_plan`] verifies that the map's current order
    /// matches this fingerprint before executing the moves.
    pub fn fingerprint(&self) -> &[K] {
        &self.fingerprint
    }
}

/// Error type for move plan generation and application.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PlanError {
    /// The target length doesn't match the map length.
    LengthMismatch,
    /// The target contains a duplicate key.
    DuplicateTarget,
    /// The target contains a key not present in the map.
    MissingKey,
    /// The map's current order doesn't match the plan's fingerprint.
    FingerprintMismatch,
}

impl core::fmt::Display for PlanError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            PlanError::LengthMismatch => {
                write!(f, "target length does not match map length")
            }
            PlanError::DuplicateTarget => {
                write!(f, "target contains a duplicate key")
            }
            PlanError::MissingKey => {
                write!(f, "target contains a key not present in the map")
            }
            PlanError::FingerprintMismatch => {
                write!(
                    f,
                    "map's current order does not match the plan's original order fingerprint"
                )
            }
        }
    }
}

impl core::error::Error for PlanError {}

/// Compute the positions of the longest increasing subsequence of `ranks`,
/// choosing the lexicographically smallest positions in case of ties.
///
/// Since `ranks` is the sequence of target ranks for each original key, the
/// LIS positions correspond to the original positions of the LCS of the
/// current and target orders.
fn lcs_positions(ranks: &[usize]) -> Vec<usize> {
    let n = ranks.len();
    if n == 0 {
        return Vec::new();
    }
    // dp[i] = length of LIS starting at index i.
    let mut dp = vec![1usize; n];
    for i in (0..n).rev() {
        let mut best = 0;
        for j in (i + 1)..n {
            if ranks[j] > ranks[i] {
                best = best.max(dp[j]);
            }
        }
        dp[i] = best + 1;
    }
    let lcs_len = *dp.iter().max().unwrap();
    // Reconstruct the lexicographically smallest positions.
    let mut positions = Vec::with_capacity(lcs_len);
    let mut start = 0;
    for k in 0..lcs_len {
        let remaining = lcs_len - k;
        let mut i = start;
        while i < n {
            if dp[i] == remaining && (k == 0 || ranks[i] > ranks[positions[k - 1]]) {
                break;
            }
            i += 1;
        }
        positions.push(i);
        start = i + 1;
    }
    positions
}

/// Compute the length of the longest increasing subsequence of `ranks`.
///
/// Since `ranks` is the sequence of target ranks for each original key,
/// the LIS length equals the LCS length of the current and target orders.
fn lcs_len(ranks: &[usize]) -> usize {
    let n = ranks.len();
    if n == 0 {
        return 0;
    }
    let mut len_from = vec![1usize; n];
    for i in (0..n).rev() {
        let mut best = 0;
        for j in (i + 1)..n {
            if ranks[j] > ranks[i] {
                best = best.max(len_from[j]);
            }
        }
        len_from[i] = best + 1;
    }
    len_from.into_iter().max().unwrap()
}

impl<K, V, S> IndexMap<K, V, S> {
    /// Generate a read-only plan to reorder the map to the target key order.
    ///
    /// The plan keeps a longest common subsequence of the current and target
    /// key orders fixed, and moves each remaining key exactly once to its
    /// target position. This minimizes the number of move operations.
    ///
    /// The target keys must correspond one-to-one with the current keys:
    /// the target must have the same length, no duplicates, and no missing
    /// keys. Otherwise, an error is returned.
    ///
    /// The plan is read-only; it does not modify the map. Use
    /// [`apply_move_plan`][Self::apply_move_plan] to execute it.
    ///
    /// # Errors
    ///
    /// Returns an error if the target keys don't correspond one-to-one with
    /// the current keys.
    ///
    /// # Examples
    ///
    /// ```
    /// use indexmap::IndexMap;
    ///
    /// let mut map: IndexMap<&str, i32> = IndexMap::new();
    /// map.insert("a", 1);
    /// map.insert("b", 2);
    /// map.insert("c", 3);
    /// map.insert("d", 4);
    ///
    /// let target = ["b", "c", "a", "d"];
    /// let plan = map.plan_move_to(&target).unwrap();
    /// assert_eq!(plan.len(), 1); // only "a" needs to move
    /// ```
    pub fn plan_move_to(&self, target: &[K]) -> Result<MovePlan<K>, PlanError>
    where
        K: Clone + Eq + Hash,
        S: BuildHasher,
    {
        let n = self.len();
        if target.len() != n {
            return Err(PlanError::LengthMismatch);
        }

        // Reject duplicate keys in the target.
        let mut seen: Vec<&K> = Vec::with_capacity(n);
        for key in target {
            if seen.contains(&key) {
                return Err(PlanError::DuplicateTarget);
            }
            seen.push(key);
        }

        // Reject target keys that aren't in the map.
        for key in target {
            if !self.contains_key(key) {
                return Err(PlanError::MissingKey);
            }
        }

        // Compute the target rank of each original key.
        let mut ranks: Vec<usize> = Vec::with_capacity(n);
        for key in self.keys() {
            let rank = target.iter().position(|k| k == key).unwrap();
            ranks.push(rank);
        }

        // The target order expressed as original positions:
        // orig_pos_of_target[i] = original position of the key at target position i.
        let mut orig_pos_of_target = vec![0usize; n];
        for orig_pos in 0..n {
            orig_pos_of_target[ranks[orig_pos]] = orig_pos;
        }

        // Find the LCS (anchors) with lexicographically smallest original
        // positions. The anchors stay fixed; each non-anchor is moved exactly
        // once to its target position.
        let anchor_positions = lcs_positions(&ranks);
        let mut is_anchor = vec![false; n];
        for &pos in &anchor_positions {
            is_anchor[pos] = true;
        }

        // Collect non-anchors sorted by increasing target rank.
        let mut non_anchors: Vec<(usize, usize)> = (0..n)
            .filter(|&pos| !is_anchor[pos])
            .map(|pos| (ranks[pos], pos))
            .collect();
        non_anchors.sort_by_key(|&(rank, _)| rank);

        // Generate the move sequence. Process non-anchors in target order,
        // moving each one to its correct position relative to the anchors and
        // previously moved non-anchors.
        let mut is_processed = vec![false; n];
        let mut state: Vec<usize> = (0..n).collect();
        let mut moves = Vec::new();
        for &(_, orig_pos) in &non_anchors {
            let target_rank = ranks[orig_pos];
            // Find the current position of this element.
            let from = state.iter().position(|&p| p == orig_pos).unwrap();
            // Remove it from the state.
            state.remove(from);
            // Find the last placed element (anchor or processed non-anchor)
            // that is before this element in target order.
            let mut to = 0;
            for (i, &p) in state.iter().enumerate() {
                let placed = is_anchor[p] || is_processed[p];
                if placed && ranks[p] < target_rank {
                    to = i + 1;
                }
            }
            // Insert at the computed position.
            state.insert(to, orig_pos);
            is_processed[orig_pos] = true;
            moves.push(Move { from, to });
        }

        debug_assert_eq!(
            state, orig_pos_of_target,
            "move plan did not achieve the target order"
        );

        // Verify the plan is minimum: the number of moves should equal
        // n - LCS length. Compute the LCS length independently.
        debug_assert_eq!(
            moves.len(),
            n - lcs_len(&ranks),
            "move plan is not minimum"
        );

        Ok(MovePlan {
            moves,
            fingerprint: self.keys().cloned().collect(),
        })
    }

    /// Apply a move plan to the map.
    ///
    /// This first verifies that the map's current key order matches the
    /// plan's original order fingerprint. If the map has been rearranged
    /// since the plan was generated, an error is returned and no moves are
    /// executed.
    ///
    /// If the fingerprint matches, the moves are executed in order,
    /// reordering the map to the target key order. Key-value bindings are
    /// unchanged.
    ///
    /// # Errors
    ///
    /// Returns [`PlanError::FingerprintMismatch`] if the map's current order
    /// doesn't match the plan's fingerprint.
    ///
    /// # Examples
    ///
    /// ```
    /// use indexmap::IndexMap;
    ///
    /// let mut map: IndexMap<&str, i32> = IndexMap::new();
    /// map.insert("a", 1);
    /// map.insert("b", 2);
    /// map.insert("c", 3);
    /// map.insert("d", 4);
    ///
    /// let target = ["b", "c", "a", "d"];
    /// let plan = map.plan_move_to(&target).unwrap();
    ///
    /// map.apply_move_plan(&plan).unwrap();
    /// assert_eq!(map.keys().copied().collect::<Vec<_>>(), vec!["b", "c", "a", "d"]);
    /// ```
    pub fn apply_move_plan(&mut self, plan: &MovePlan<K>) -> Result<(), PlanError>
    where
        K: Eq,
    {
        // Verify the fingerprint: the map's current key order must match
        // the plan's original key order.
        if self.len() != plan.fingerprint.len() {
            return Err(PlanError::FingerprintMismatch);
        }
        for (i, key) in self.keys().enumerate() {
            if key != &plan.fingerprint[i] {
                return Err(PlanError::FingerprintMismatch);
            }
        }

        // Execute the moves in order.
        for mv in &plan.moves {
            self.move_index(mv.from, mv.to);
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::vec::Vec;

    fn map_from(keys: &[&'static str]) -> IndexMap<&'static str, i32> {
        let mut map = IndexMap::new();
        for (i, &k) in keys.iter().enumerate() {
            map.insert(k, i as i32);
        }
        map
    }

    fn keys_of(map: &IndexMap<&'static str, i32>) -> Vec<&'static str> {
        map.keys().copied().collect()
    }

    #[test]
    fn basic_move_a_once() {
        let mut map = map_from(&["a", "b", "c", "d"]);
        let target = ["b", "c", "a", "d"];
        let plan = map.plan_move_to(&target).unwrap();
        assert_eq!(plan.len(), 1, "only one move should be needed");
        assert_eq!(plan.moves()[0], Move { from: 0, to: 2 });
        map.apply_move_plan(&plan).unwrap();
        assert_eq!(keys_of(&map), vec!["b", "c", "a", "d"]);
        // Values are unchanged.
        assert_eq!(map[&"a"], 0);
        assert_eq!(map[&"b"], 1);
        assert_eq!(map[&"c"], 2);
        assert_eq!(map[&"d"], 3);
    }

    #[test]
    fn already_in_order() {
        let mut map = map_from(&["a", "b", "c", "d"]);
        let target = ["a", "b", "c", "d"];
        let plan = map.plan_move_to(&target).unwrap();
        assert!(plan.is_empty());
        map.apply_move_plan(&plan).unwrap();
        assert_eq!(keys_of(&map), vec!["a", "b", "c", "d"]);
    }

    #[test]
    fn reverse_order() {
        let mut map = map_from(&["a", "b", "c", "d"]);
        let target = ["d", "c", "b", "a"];
        let plan = map.plan_move_to(&target).unwrap();
        // LCS length is 1, so 4 - 1 = 3 moves.
        assert_eq!(plan.len(), 3);
        map.apply_move_plan(&plan).unwrap();
        assert_eq!(keys_of(&map), vec!["d", "c", "b", "a"]);
    }

    #[test]
    fn duplicate_key_rejected() {
        let map = map_from(&["a", "b", "c"]);
        let target = ["a", "b", "a"];
        let err = map.plan_move_to(&target).unwrap_err();
        assert_eq!(err, PlanError::DuplicateTarget);
    }

    #[test]
    fn missing_key_rejected() {
        let map = map_from(&["a", "b", "c"]);
        let target = ["a", "b", "d"];
        let err = map.plan_move_to(&target).unwrap_err();
        assert_eq!(err, PlanError::MissingKey);
    }

    #[test]
    fn length_mismatch_rejected() {
        let map = map_from(&["a", "b", "c"]);
        let target = ["a", "b"];
        let err = map.plan_move_to(&target).unwrap_err();
        assert_eq!(err, PlanError::LengthMismatch);
    }

    #[test]
    fn empty_map() {
        let mut map: IndexMap<&str, i32> = IndexMap::new();
        let target: [&str; 0] = [];
        let plan = map.plan_move_to(&target).unwrap();
        assert!(plan.is_empty());
        assert!(plan.fingerprint().is_empty());
        map.apply_move_plan(&plan).unwrap();
        assert!(map.is_empty());
    }

    #[test]
    fn fingerprint_mismatch_rejected() {
        let mut map = map_from(&["a", "b", "c", "d"]);
        let target = ["b", "c", "a", "d"];
        let plan = map.plan_move_to(&target).unwrap();
        // Rearrange the map externally.
        map.swap_indices(0, 1);
        let err = map.apply_move_plan(&plan).unwrap_err();
        assert_eq!(err, PlanError::FingerprintMismatch);
        // The map should be unchanged (no moves executed).
        assert_eq!(keys_of(&map), vec!["b", "a", "c", "d"]);
    }

    #[test]
    fn plan_is_read_only() {
        let map = map_from(&["a", "b", "c", "d"]);
        let target = ["b", "c", "a", "d"];
        let plan = map.plan_move_to(&target).unwrap();
        // Generating the plan doesn't modify the map.
        assert_eq!(keys_of(&map), vec!["a", "b", "c", "d"]);
        // Applying doesn't modify the plan.
        let mut map2 = map.clone();
        map2.apply_move_plan(&plan).unwrap();
        assert_eq!(plan.len(), 1);
        assert_eq!(plan.fingerprint(), &["a", "b", "c", "d"]);
    }

    /// Compute the LCS length of two slices (for test verification).
    fn lcs_len(a: &[&str], b: &[&str]) -> usize {
        let n = a.len();
        let m = b.len();
        let mut dp = vec![vec![0usize; m + 1]; n + 1];
        for i in 0..n {
            for j in 0..m {
                if a[i] == b[j] {
                    dp[i + 1][j + 1] = dp[i][j] + 1;
                } else {
                    dp[i + 1][j + 1] = dp[i][j + 1].max(dp[i + 1][j]);
                }
            }
        }
        dp[n][m]
    }

    /// Exhaustively verify the move plan on all permutations of `n` keys.
    ///
    /// For each pair of permutations (current, target), verify:
    /// - The plan achieves the target order.
    /// - The number of moves is minimum (n - LCS length).
    /// - The values are unchanged.
    fn exhaustive_permutations(n: usize) {
        let keys: Vec<&str> = (0..n)
            .map(|i| match i {
                0 => "a",
                1 => "b",
                2 => "c",
                3 => "d",
                4 => "e",
                5 => "f",
                6 => "g",
                7 => "h",
                _ => unreachable!(),
            })
            .collect();

        // Generate all permutations of the keys.
        let mut perms: Vec<Vec<&str>> = Vec::new();
        let mut indices: Vec<usize> = (0..n).collect();
        loop {
            perms.push(indices.iter().map(|&i| keys[i]).collect());
            // Find the next permutation.
            let mut k = None;
            for i in (0..n - 1).rev() {
                if indices[i] < indices[i + 1] {
                    k = Some(i);
                    break;
                }
            }
            let k = match k {
                Some(k) => k,
                None => break,
            };
            let mut l = k + 1;
            for i in (k + 1..n).rev() {
                if indices[i] > indices[k] {
                    l = i;
                    break;
                }
            }
            indices.swap(k, l);
            indices[k + 1..].reverse();
        }

        for current in &perms {
            for target in &perms {
                let mut map = map_from(current);
                let plan = map.plan_move_to(target).unwrap();
                let expected_min = n - lcs_len(current, target);
                assert_eq!(
                    plan.len(),
                    expected_min,
                    "non-minimum moves for current={:?} target={:?}",
                    current,
                    target
                );
                map.apply_move_plan(&plan).unwrap();
                assert_eq!(
                    keys_of(&map),
                    *target,
                    "target not achieved for current={:?} target={:?}",
                    current,
                    target
                );
                // Values unchanged: each key's value is its original index.
                for (i, &k) in current.iter().enumerate() {
                    assert_eq!(map[&k], i as i32);
                }
            }
        }
    }

    #[test]
    fn exhaustive_n2() {
        exhaustive_permutations(2);
    }

    #[test]
    fn exhaustive_n3() {
        exhaustive_permutations(3);
    }

    #[test]
    fn exhaustive_n4() {
        exhaustive_permutations(4);
    }

    #[test]
    fn exhaustive_n5() {
        exhaustive_permutations(5);
    }

    #[test]
    fn exhaustive_n6() {
        exhaustive_permutations(6);
    }
}